#[test]
fn original_destination_initialization_preserves_paid_page_custody_at_every_abandonment(){
 fn now()->Option<u64>{Some(1)}
 let _lease=worker_session_slots_exclusive();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(99931),Generation(4),WORKER_TEST_STOCK,now,2,20000);let mut initial_turns=0;while worker_job_retirements_are_parked(){let(step,heap)=observe(||caller.turn(grant,|cx|pump_worker_job_retirements(1,cx)).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);initial_turns+=1;assert!(initial_turns<8192);}
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../👷️worker/🚪️admission/🚚️staged/📦️destination/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let actual=law["layouts"].as_array().unwrap().iter().find(|row|row["pointerBytes"].as_u64().unwrap()as usize==size_of::<usize>()).unwrap();assert_eq!((OriginalWorkerPayload::initialization_copy_bytes()-size_of::<usize>())/JOB_PAYLOAD_OPERATION_PAGES,actual["slotBytes"].as_u64().unwrap()as usize);
 for cut in 0..=3{
  let identity=(OperationId(99931),Generation(4));let mut storage=MaybeUninit::<WorkerJobSource<TerminalJob<0>>>::uninit();let mut recipient=Default::default();let mut cx=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut recipient).unwrap();let(source,_)=WorkerJobSource::start_preparation(&mut storage,&mut cx).unwrap().unwrap();drop(cx);let mut initializer=TerminalSourceInitializer::<0>{written:0};let mut receipt=Default::default();let mut cx=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut receipt).unwrap();assert!(source.prepare_step(&mut initializer,&mut cx).unwrap().complete);drop(cx);let pointer=source.source().unwrap()as*const _;let mut params=Some(BatchJobParams{operation:identity.0,generation:identity.1,cancel:caller.admit_alias(grant),config:BatchDriveConfig{site:"test.original-destination",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1,retained:grant},now_us:now});let mut recipient=Default::default();let mut cx=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut recipient).unwrap();let((mut admission,birth),heap)=observe(||WorkerJobAdmission::try_begin(source,&mut params,&mut cx).unwrap().unwrap());drop(cx);assert_eq!(birth,recipient);assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);let page=admission.destination_page_identity().unwrap();let born=heap.0;let mut paid=Vec::new();
  for _ in 0..cut{if admission.destination_is_initialized(){break}let demand=admission.destination_initialization_demands().unwrap();assert!(demand.copy_bytes<=4096);for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut recipient=Default::default();let mut cx=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,denied),now,&mut recipient).unwrap();let(step,heap)=observe(||admission.advance_destination_initialization(&mut cx).unwrap());drop(cx);assert_eq!(step,Default::default());assert_eq!(recipient,Default::default());assert_eq!(heap,(0,0));assert_eq!(admission.destination_page_identity(),Some(page));assert_eq!(admission.source()as*const _,pointer);}
   let mut recipient=Default::default();let mut cx=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut recipient).unwrap();let(step,heap)=observe(||admission.advance_destination_initialization(&mut cx).unwrap());drop(cx);assert_eq!(step,recipient);assert!(step.fits(grant));assert_eq!(heap,(0,0));assert_eq!(admission.destination_page_identity(),Some(page));assert_eq!(admission.source()as*const _,pointer);paid.push(step.copied_bytes);
  }
  let(_,heap)=observe(||drop(admission));assert_eq!(heap,(0,0));assert!(params.is_some());assert_eq!(source.source().unwrap()as*const _,pointer);let mut released=0;let mut turns=0;while worker_job_retirements_are_parked(){let(step,heap)=observe(||caller.turn(grant,|cx|pump_worker_job_retirements(1,cx)).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;turns+=1;assert!(turns<64);}assert_eq!(released,born);caller.turn(grant,|cx|source.retire_terminal_step(cx)).unwrap();assert!(source.source().is_none());caller.return_alias(params.take().unwrap().cancel,grant);eprintln!("[DEBUG] original destination cut={cut} same prepaid page={page:p} source pointer unchanged initializedCopies={paid:?} exact born/free={born}/{released} abandoned Drop0 original4096");
 }
 caller.retire(grant);
}
